program.source:
Funcion impuesto <- Iva(precio Como Entero)
  Definir impuesto Como Entero;
  Escribir "Calculando el IVA";
  impuesto <- precio * 21 div 100;
FinFuncion

Algoritmo Principal
  Definir precio Como Entero;
  Leer precio;
  Escribir "IVA: ", Iva(precio);
FinAlgoritmo

